package com.mfg.srm.controller;import com.mfg.common.api.ApiResponse;import com.mfg.common.service.P3CrudService;import com.mfg.common.service.P3FlowService;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.Page;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController @RequestMapping("/api/srm") @RequiredArgsConstructor public class SrmP3Controller{private final P3CrudService s;private final P3FlowService flow;private static final java.util.Set<String>K=java.util.Set.of("onboarding","rfqs","quotes","asns","supplier-quality","performance");private String k(String k){if(!K.contains(k))throw new IllegalArgumentException("不支持的SRM对象");return k;}@GetMapping("/{kind}")public ApiResponse<Page<Map<String,Object>>>page(@PathVariable String kind,@RequestParam(required=false)String keyword,@RequestParam(required=false)String status,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.ok(s.page(k(kind),keyword,status,page,size));}@GetMapping("/{kind}/{id}")public ApiResponse<Map<String,Object>>detail(@PathVariable String kind,@PathVariable long id){return ApiResponse.ok(s.detail(k(kind),id));}@PostMapping("/{kind}")public ApiResponse<Map<String,Object>>create(@PathVariable String kind,@RequestBody Map<String,Object>x){return ApiResponse.ok(s.create(k(kind),x));}@PostMapping("/{kind}/{id}/status")public ApiResponse<Map<String,Object>>status(@PathVariable String kind,@PathVariable long id,@RequestBody Map<String,Object>x){return ApiResponse.ok(s.status(k(kind),id,String.valueOf(x.get("status"))));}@PostMapping("/rfqs/{id}/award")public ApiResponse<Map<String,Object>>award(@PathVariable long id,@RequestParam long quoteId){return ApiResponse.ok(flow.awardRfq(id,quoteId));}@PostMapping("/asns/{id}/arrive")public ApiResponse<Map<String,Object>>arrive(@PathVariable long id,@RequestParam(defaultValue="WH01")String warehouseCode){return ApiResponse.ok(flow.arriveAsn(id,warehouseCode));}}
